public class Main {static class Fast {byte[] b=new byte[65536];int p,l;int read()throws Exception{if(p==l){l=System.in.read(b);p=0;if(l<0)return -1;}return b[p++];}int next()throws Exception{int c;do{c=read();}while(c<=32&&c!=-1);int x=0;while(c>32){x=x*10+c-48;c=read();}return x;}}
public static void main(String[] args)throws Exception{Fast in=new Fast();int t=in.next();StringBuilder out=new StringBuilder();while(t-->0){int n=in.next(),x=in.next();long[] prefix=new long[n+1];for(int i=1;i<=n;i++)prefix[i]=prefix[i-1]+in.next();long answer=0;for(int k=1;k<=n&&2L*k*k<=x;k++){if(x%k!=0)continue;int target=x/k;int[] freq=new int[target+1];for(int i=k;i<=n;i++){long sum=prefix[i]-prefix[i-k];if(sum<target)freq[(int)sum]++;}for(int sum=k;sum<target;sum++)answer+=(long)freq[sum]*freq[target-sum];}out.append(answer).append('\n');}System.out.print(out);}}
